window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4332cbb2939a7b2c"]={"versions": [{"id": "FIG-4332cbb2939a7b2c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Gegenüberstellung von asynchroner und synchroner Ereignisverarbeitung (Event Processing) im AUTOSAR Diagnostic Event Manager (Dem) unter Einbindung von Software-Components (SW-C) bzw. Basis-Softwaremodulen (BSW). Das Diagramm visualisiert die Ausführungskontexte über zwei getrennte Sequenzrahmen hinweg: oben die Entkopplung über Warteschlangen (asynchronous behavior), unten die direkte Verarbeitung im Kontext des Aufrufers (synchronous behavior).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien repräsentieren funktionale bzw. architektonische Einheiten:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufender Kontext (Software-Component oder BSW-Modul).</li>\n<li><code>Dem queuing (asynchronous)</code>: Pufferungs- und Warteschlangenmechanismus des Dem für die asynchrone Entgegennahme von Ereignissen.</li>\n<li><code>Dem processing</code>: Ausführungskontext der internen Dem-Ereignisverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte (große Rahmen):</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext der aufrufenden Komponente.</li>\n<li><code>Dem main function</code>: Zyklischer Hauptfunktionskontext des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionsnachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Update event status()</code>: Synchroner Aufruf zur Aktualisierung des Fehlerstatus.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch die zyklische Dem-Hauptfunktion.</li>\n<li><code>Start internal event processing()</code>: Interner Selbstaufruf (Reflexivaufruf) zur Weiterverarbeitung des Ereignisses.</li>\n<li>Gestrichelte Pfeile für synchrone Rückmeldungen (Execution Returns).</li>\n<li>Notizen zur Klassifizierung: <code>asynchronous behavior</code> und <code>synchronous behavior</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei alternative Verhaltensszenarien:</p>\n<ol class=\"fig-list\">\n<li>Asynchrones Verhalten (<code>asynchronous behavior</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb des <code>SW-C or BSW Task</code> ruft die Lebenslinie <code>SW-C or BSW</code> auf der Lebenslinie <code>Dem queuing (asynchronous)</code> synchron die Operation <code>Update event status()</code> auf. Nach Einreihung des Events in die Queue erfolgt der Rücksprung zum Aufrufer.</li>\n<li>Zeitlich entkoppelt ruft die Lebenslinie <code>Dem processing</code> innerhalb der zyklischen <code>Dem main function</code> synchron die Operation <code>Ask for queued events()</code> an <code>Dem queuing (asynchronous)</code> auf. Nach Rückmeldung der gepufferten Ereignisdaten führt <code>Dem processing</code> über den reflexiven Aufruf <code>Start internal event processing()</code> die interne Verarbeitung aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Synchrones Verhalten (<code>synchronous behavior</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb des <code>SW-C or BSW Task</code> ruft die Lebenslinie <code>SW-C or BSW</code> direkt die Lebenslinie <code>Dem processing</code> über <code>Update event status()</code> auf.</li>\n<li>Noch im Ausführungskontext des <code>SW-C or BSW Task</code> führt <code>Dem processing</code> unmittelbar den Selbstaufruf <code>Start internal event processing()</code> aus und liefert das Ergebnis anschließend synchron an die aufrufende Komponente zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Laufzeitverhalten und die Task-Entkopplung gemäß AUTOSAR-Dem-Spezifikation. Entwickler müssen berücksichtigen:</p>\n<ul class=\"fig-list\">\n<li>Beim asynchronen Pfad erfolgt der Aufruf von <code>Update event status()</code> nicht-blockierend bezüglich der eigentlichen Dem-Verarbeitungslogik (z. B. Debouncing, Fehlerspeicherverwaltung); die Ausführung erfolgt verzögert in der periodischen <code>Dem_MainFunction()</code>.</li>\n<li>Beim synchronen Pfad bindet die vollständige interne Zustandsaktualisierung (<code>Start internal event processing()</code>) Rechenzeit im Task des Aufrufers (<code>SW-C or BSW Task</code>), was Auswirkungen auf Echtzeitanforderungen und Worst-Case Execution Time (WCET) hat.</li>\n<li>Die Wahl zwischen synchroner und asynchroner Anbindung hängt von der Konfiguration und den Latenzanforderungen des jeweiligen Diagnoseereignisses ab.</li>\n</ul>"}, {"id": "FIG-26484590471fcff7", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Gegenüberstellung von asynchroner und synchroner Ereignisverarbeitung (Event Processing) im AUTOSAR Diagnostic Event Manager (Dem) unter Einbindung von Software-Components (SW-C) bzw. Basis-Softwaremodulen (BSW). Das Diagramm visualisiert die Ausführungskontexte über zwei getrennte Sequenzrahmen hinweg: oben die Entkopplung über Warteschlangen (asynchronous behavior), unten die direkte Verarbeitung im Kontext des Aufrufers (synchronous behavior).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien repräsentieren funktionale bzw. architektonische Einheiten:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufender Kontext (Software-Component oder BSW-Modul).</li>\n<li><code>Dem queuing (asynchronous)</code>: Pufferungs- und Warteschlangenmechanismus des Dem für die asynchrone Entgegennahme von Ereignissen.</li>\n<li><code>Dem processing</code>: Ausführungskontext der internen Dem-Ereignisverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte (große Rahmen):</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext der aufrufenden Komponente.</li>\n<li><code>Dem main function</code>: Zyklischer Hauptfunktionskontext des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionsnachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Update event status()</code>: Synchroner Aufruf zur Aktualisierung des Fehlerstatus.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch die zyklische Dem-Hauptfunktion.</li>\n<li><code>Start internal event processing()</code>: Interner Selbstaufruf (Reflexivaufruf) zur Weiterverarbeitung des Ereignisses.</li>\n<li>Gestrichelte Pfeile für synchrone Rückmeldungen (Execution Returns).</li>\n<li>Notizen zur Klassifizierung: <code>asynchronous behavior</code> und <code>synchronous behavior</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei alternative Verhaltensszenarien:</p>\n<ol class=\"fig-list\">\n<li>Asynchrones Verhalten (<code>asynchronous behavior</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb des <code>SW-C or BSW Task</code> ruft die Lebenslinie <code>SW-C or BSW</code> auf der Lebenslinie <code>Dem queuing (asynchronous)</code> synchron die Operation <code>Update event status()</code> auf. Nach Einreihung des Events in die Queue erfolgt der Rücksprung zum Aufrufer.</li>\n<li>Zeitlich entkoppelt ruft die Lebenslinie <code>Dem processing</code> innerhalb der zyklischen <code>Dem main function</code> synchron die Operation <code>Ask for queued events()</code> an <code>Dem queuing (asynchronous)</code> auf. Nach Rückmeldung der gepufferten Ereignisdaten führt <code>Dem processing</code> über den reflexiven Aufruf <code>Start internal event processing()</code> die interne Verarbeitung aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Synchrones Verhalten (<code>synchronous behavior</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb des <code>SW-C or BSW Task</code> ruft die Lebenslinie <code>SW-C or BSW</code> direkt die Lebenslinie <code>Dem processing</code> über <code>Update event status()</code> auf.</li>\n<li>Noch im Ausführungskontext des <code>SW-C or BSW Task</code> führt <code>Dem processing</code> unmittelbar den Selbstaufruf <code>Start internal event processing()</code> aus und liefert das Ergebnis anschließend synchron an die aufrufende Komponente zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Laufzeitverhalten und die Task-Entkopplung gemäß AUTOSAR-Dem-Spezifikation. Entwickler müssen berücksichtigen:</p>\n<ul class=\"fig-list\">\n<li>Beim asynchronen Pfad erfolgt der Aufruf von <code>Update event status()</code> nicht-blockierend bezüglich der eigentlichen Dem-Verarbeitungslogik (z. B. Debouncing, Fehlerspeicherverwaltung); die Ausführung erfolgt verzögert in der periodischen <code>Dem_MainFunction()</code>.</li>\n<li>Beim synchronen Pfad bindet die vollständige interne Zustandsaktualisierung (<code>Start internal event processing()</code>) Rechenzeit im Task des Aufrufers (<code>SW-C or BSW Task</code>), was Auswirkungen auf Echtzeitanforderungen und Worst-Case Execution Time (WCET) hat.</li>\n<li>Die Wahl zwischen synchroner und asynchroner Anbindung hängt von der Konfiguration und den Latenzanforderungen des jeweiligen Diagnoseereignisses ab.</li>\n</ul>"}, {"id": "FIG-9007cfabcb282212", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}, {"id": "FIG-7e686035798db7e9", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}, {"id": "FIG-8b67252320c705ef", "releases": ["R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}, {"id": "FIG-c36b5c853cc77e45", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}, {"id": "FIG-d80b4987171d15bd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}, {"id": "FIG-79dba36d8c631a46", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur asynchronen Ereignisverarbeitung im AUTOSAR Diagnostic Event Manager (Dem) unter Aufteilung zwischen Task-Kontext der aufrufenden Komponente und Hauptfunktionskontext des Dem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW</code>: Aufrufende Software-Component oder Basis-Software.</li>\n<li><code>«module» Dem</code>: Schnittstelle und Modulinstanz des Diagnostic Event Manager.</li>\n<li><code>Dem processing</code>: Interne Verarbeitungsinstanz des Dem.</li>\n</ul>\n<p class=\"fig-p\">Ausführungskontexte:</p>\n<ul class=\"fig-list\">\n<li><code>SW-C or BSW Task</code>: Task-Kontext des Meldenden.</li>\n<li><code>Dem main function</code>: Zyklische Hauptfunktion des Dem.</li>\n</ul>\n<p class=\"fig-p\">Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>Dem_SetEventStatus()</code>: API-Aufruf von <code>SW-C or BSW</code> an <code>«module» Dem</code> mit synchroner Rückkehr.</li>\n<li><code>Ask for queued events()</code>: Synchroner Abruf gepufferter Ereignisse durch <code>Dem processing</code> an <code>«module» Dem</code>.</li>\n<li><code>Process UDS status()</code>: Reflexive Operationsausführung innerhalb der Lebenslinie <code>Dem processing</code>.</li>\n<li>Notiz: <code>Process monitor status</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Einbindung im Melde-Task: Innerhalb des <code>SW-C or BSW Task</code> setzt der Aufrufer über <code>Dem_SetEventStatus()</code> den Monitor-Status am Modul <code>Dem</code> ab. Nach Verarbeitung/Pufferung des Monitor-Status (<code>Process monitor status</code>) kehrt der Aufruf unmittelbar per Return-Pfeil zurück.</li>\n<li>Periodische Abarbeitung: Die zyklische <code>Dem main function</code> initiiert über <code>Dem processing</code> mit <code>Ask for queued events()</code> die Abfrage gepufferter Ereignisse an <code>«module» Dem</code>.</li>\n<li>Nach Rückgabe der Ereignisdaten startet <code>Dem processing</code> über den internen Reflexivaufruf <code>Process UDS status()</code> die eigentliche Berechnung und Aktualisierung der UDS-Statusbits.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Trennung zwischen Meldungsannahme (Monitor-Status über <code>Dem_SetEventStatus()</code>) und der UDS-Statusbit-Verarbeitung (<code>Process UDS status()</code>).</li>\n<li>Die Schnittstelle <code>Dem_SetEventStatus()</code> verarbeitet den Monitor-Status im Kontext des Aufrufers und puffert das Ereignis für die asynchrone Weiterverarbeitung, um die Tasklaufzeit des Aufrufers zu minimieren.</li>\n<li>Die eigentliche Qualifikation und UDS-Fehlerspeicheraktualisierung erfolgt entkoppelt innerhalb der periodischen <code>Dem_MainFunction()</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-4332cbb2939a7b2c", "to": "FIG-26484590471fcff7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-26484590471fcff7", "to": "FIG-9007cfabcb282212", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Unterer Sequenzrahmen für das synchrone Verhalten (<code>synchronous behavior</code>) mit dem direkten Aufruf <code>Update event status()</code> und <code>Start internal event processing()</code> aus dem SW-C/BSW-Task entfällt vollständig.</li>\n<li>Lebenslinie <code>Dem queuing (asynchronous)</code> umbenannt und typisiert zu <code>«module» Dem</code>.</li>\n<li>Operationsaufruf <code>Update event status()</code> spezifiziert als Standard-API-Funktion <code>Dem_SetEventStatus()</code>.</li>\n<li>Kommentar-Notiz <code>asynchronous behavior</code> ersetzt durch <code>Process monitor status</code>.</li>\n<li>Interne Selbstaufruf-Aktion <code>Start internal event processing()</code> innerhalb der <code>Dem main function</code> umbenannt in <code>Process UDS status()</code>.</li>\n</ul>"}, {"from": "FIG-9007cfabcb282212", "to": "FIG-7e686035798db7e9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7e686035798db7e9", "to": "FIG-8b67252320c705ef", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8b67252320c705ef", "to": "FIG-7e686035798db7e9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8b67252320c705ef", "to": "FIG-c36b5c853cc77e45", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c36b5c853cc77e45", "to": "FIG-7e686035798db7e9", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7e686035798db7e9", "to": "FIG-d80b4987171d15bd", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d80b4987171d15bd", "to": "FIG-79dba36d8c631a46", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
